import { GameControls } from "../Controls/GameControls";
import { BaseComponent } from "../../../utils/baseElement";
import { GameBoard } from "../../GameBoard/GameBoard";
import styles from "./Main.module.scss";
import { stateMachine } from "../../../core/StateMachine";
import { ControlButtonsController } from "../Controls/ControlButtonsController";
import { TemplateSelector } from "../Controls/TemplateSelector";
import { levelConfig } from "../../../core/levelConfig";
import { TemplateController } from "../Controls/TemplateController";
import { CellController } from "../../Cell/CellController";

class Main extends BaseComponent {
  /**
   *
   * @param {string} tag
   * @param {string} className
   */
  constructor() {
    super({ tag: "main", className: styles.main });
    this.getNode();
    this.addInvitation();
    this.addTemplateSelector();
    this.addControls();
    this.controlsManager = new ControlButtonsController(
      stateMachine,
      this.controls,
    );
    this.templateManager = new TemplateController(
      levelConfig,
      stateMachine,
      this.templateSelector,
    );

    this.cellController = new CellController(levelConfig, stateMachine);

    this.addGameBoard();
  }
  addInvitation() {
    this.h2 = new BaseComponent({
      tag: "h2",
      className: styles.invitation,
      text: "Hi! Do you wanna choose a game? ",
    });
    this.append(this.h2);
  }

  addTemplateSelector() {
    this.templateSelector = new TemplateSelector(levelConfig);
    this.append(this.templateSelector);
  }

  addControls() {
    this.controls = new GameControls();
    this.append(this.controls);
  }

  addGameBoard() {
    this.gameBoard = new GameBoard(this.templateManager, this.cellController);
    this.append(this.gameBoard);
  }
}

export { Main }; //wrapper
